#!/bin/bash
# OpenUSD (the org's fork) static for wasm32-wasip1, no threads, no exceptions, via wasi-sdk 34.
set -e
cd "$(dirname "$0")"; R=$PWD; W=$R/wasi-sdk-34.0-arm64-macos
F="-include $R/shim/compat.h -fignore-exceptions -D__unix__=1 -D__EMSCRIPTEN__=1 -I$R/shim -D_WASI_EMULATED_MMAN -D_WASI_EMULATED_PROCESS_CLOCKS -D_WASI_EMULATED_SIGNAL -D_WASI_EMULATED_GETPID -DTBB_USE_EXCEPTIONS=0 -ffile-prefix-map=$R/src/usd/=openusd/"
export CXXFLAGS="$F -include cstdlib -include algorithm" CFLAGS="$F"
cmake -S src/usd -B usd -G Ninja -DEMSCRIPTEN=ON -DCMAKE_CXX_STANDARD=17 -DCMAKE_CXX_STANDARD_REQUIRED=ON -DCMAKE_TOOLCHAIN_FILE=$W/share/cmake/wasi-sdk-p1.cmake -DWASI_SDK_PREFIX=$W -DCMAKE_BUILD_TYPE=Release -DBUILD_SHARED_LIBS=OFF -DPXR_BUILD_MONOLITHIC=OFF -DPXR_ENABLE_PYTHON_SUPPORT=OFF -DPXR_BUILD_IMAGING=OFF -DPXR_BUILD_USD_IMAGING=OFF -DPXR_BUILD_USDVIEW=OFF -DPXR_BUILD_TESTS=OFF -DPXR_BUILD_EXAMPLES=OFF -DPXR_BUILD_TUTORIALS=OFF -DPXR_BUILD_USD_TOOLS=OFF -DPXR_BUILD_HTML_DOCUMENTATION=OFF -DPXR_ENABLE_MATERIALX_SUPPORT=OFF -DPXR_ENABLE_OPENVDB_SUPPORT=OFF -DPXR_ENABLE_PTEX_SUPPORT=OFF -DPXR_BUILD_ALEMBIC_PLUGIN=OFF -DPXR_BUILD_DRACO_PLUGIN=OFF -DPXR_ENABLE_OSL_SUPPORT=OFF -DPXR_PREFER_SAFETY_OVER_SPEED=ON -DTBB_ROOT=$R/inst -DTBB_DIR=$R/inst/lib/cmake/TBB
